// Weekly report: ads that became "winning" (running 30+ days and still live) in the last 7 days, and new launches.
const DAYS = 7;
const rows = $input.all().map(i => i.json);
const ok = rows.filter(r => r.status === 'ok');
const noAds = rows.filter(r => r.status && r.status !== 'ok');
const ageDays = d => (Date.now() - Date.parse(d + 'T00:00:00Z')) / 864e5;
const newWinners = ok.filter(r => r.isWinningAd && r.daysActive <= 30 + DAYS);
const launches = ok.filter(r => r.firstShownDate && ageDays(r.firstShownDate) <= DAYS);
const allWinners = ok.filter(r => r.isWinningAd);
const line = r => `• *${r.inputDomain}* · ${r.format}${r.headline ? ` · "${r.headline}"` : ''} · ${r.daysActive} days · <${r.transparencyUrl}|view>`;
const text = [
  `*Competitor Google Ads — weekly report* (${ok.length} ads checked, ${allWinners.length} winning ads running 30+ days)`,
  `*New winning ads this week* (crossed 30 days, still running): ${newWinners.length}`,
  ...newWinners.slice(0, 15).map(line),
  `*New ads launched in the last ${DAYS} days*: ${launches.length}`,
  ...launches.slice(0, 15).map(line),
  noAds.length ? `_No ads / not checked: ${noAds.map(r => `${r.inputDomain} (${r.status})`).join(', ')}_` : '',
].filter(Boolean).join('\n');
const tag = (r, type) => ({ ...r, reportType: type });
return [{ json: { text, ads: [...newWinners.map(r => tag(r, 'New winner')), ...launches.map(r => tag(r, 'New launch'))] } }];
